package dev.hrutvik.filesync.verification;
import dev.hrutvik.filesync.blob.MultipartBlobGateway; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import org.junit.jupiter.api.Test; import java.time.Duration; import java.util.*; import static org.mockito.Mockito.*;
class BlobVerificationWorkerTest {
 @Test void verifiesMatchingBlob(){var store=mock(BlobVerificationStore.class);var blobs=mock(MultipartBlobGateway.class);var id=UUID.randomUUID();when(store.claim(anyString(),eq(10),any())).thenReturn(List.of(new BlobVerificationStore.Candidate(id,"key","abc")));when(blobs.sha256("key")).thenReturn("abc");new BlobVerificationWorker(store,blobs,new SimpleMeterRegistry(),10,Duration.ofMinutes(1)).verify();verify(store).verified(eq(id),anyString());}
 @Test void rejectsMismatchedBlob(){var store=mock(BlobVerificationStore.class);var blobs=mock(MultipartBlobGateway.class);var id=UUID.randomUUID();when(store.claim(anyString(),eq(10),any())).thenReturn(List.of(new BlobVerificationStore.Candidate(id,"key","abc")));when(blobs.sha256("key")).thenReturn("bad");new BlobVerificationWorker(store,blobs,new SimpleMeterRegistry(),10,Duration.ofMinutes(1)).verify();verify(store).rejected(eq(id),anyString(),eq("content hash mismatch"));}
 @Test void releasesLeaseOnTransientFailure(){var store=mock(BlobVerificationStore.class);var blobs=mock(MultipartBlobGateway.class);var id=UUID.randomUUID();when(store.claim(anyString(),eq(10),any())).thenReturn(List.of(new BlobVerificationStore.Candidate(id,"key","abc")));when(blobs.sha256("key")).thenThrow(new IllegalStateException());new BlobVerificationWorker(store,blobs,new SimpleMeterRegistry(),10,Duration.ofMinutes(1)).verify();verify(store).release(eq(id),anyString());}
}

